#include <iomanip>
#include <iostream>

int main()
{
    int correct{};
    int total{};
    std::cin >> correct >> total;

    double percent{ static_cast<double>(correct) / total * 100 };
    std::cout << correct << " of " << total << " correct: " << std::fixed << std::setprecision(1) << percent << "%\n";
    return 0;
}
